-- PostgreSQL Offical Documentation for 9.8 Data Type Formatting Functions: https://www.postgresql.org/docs/current/functions-formatting.html
\copy (SELECT COALESCE(as_of_year::TEXT, '') AS as_of_year, COALESCE(respondent_id::TEXT, '') AS respondent_id, COALESCE(agency_name::TEXT, '') AS agency_name, COALESCE(agency_abbr::TEXT, '') AS agency_abbr, COALESCE(agency_code::TEXT, '') AS agency_code, COALESCE(loan_type_name::TEXT, '') AS loan_type_name, COALESCE(loan_type::TEXT, '') AS loan_type, COALESCE(property_type_name::TEXT, '') AS property_type_name, COALESCE(property_type::TEXT, '') AS property_type, COALESCE(loan_purpose_name::TEXT, '') AS loan_purpose_name, COALESCE(loan_purpose::TEXT, '') AS loan_purpose, COALESCE(owner_occupancy_name::TEXT, '') AS owner_occupancy_name, COALESCE(owner_occupancy::TEXT, '') AS owner_occupancy, COALESCE(loan_amount_000s::TEXT, '') AS loan_amount_000s, COALESCE(preapproval_name::TEXT, '') AS preapproval_name, COALESCE(preapproval::TEXT, '') AS preapproval, COALESCE(action_taken_name::TEXT, '') AS action_taken_name, COALESCE(action_taken::TEXT, '') AS action_taken, COALESCE(msamd_name::TEXT, '') AS msamd_name, COALESCE(msamd::TEXT, '') AS msamd, COALESCE(state_name::TEXT, '') AS state_name, COALESCE(state_abbr::TEXT, '') AS state_abbr, COALESCE(state_code::TEXT, '') AS state_code, COALESCE(county_name::TEXT, '') AS county_name, COALESCE(county_code::TEXT, '') AS county_code, COALESCE(TO_CHAR(census_tract_number, 'FM0000.00'), '') AS census_tract_number, COALESCE(applicant_ethnicity_name::TEXT, '') AS applicant_ethnicity_name, COALESCE(applicant_ethnicity::TEXT, '') AS applicant_ethnicity, COALESCE(co_applicant_ethnicity_name::TEXT, '') AS co_applicant_ethnicity_name, COALESCE(co_applicant_ethnicity::TEXT, '') AS co_applicant_ethnicity, COALESCE(applicant_race_name_1::TEXT, '') AS applicant_race_name_1, COALESCE(applicant_race_1::TEXT, '') AS applicant_race_1, COALESCE(applicant_race_name_2::TEXT, '') AS applicant_race_name_2, COALESCE(applicant_race_2::TEXT, '') AS applicant_race_2, COALESCE(applicant_race_name_3::TEXT, '') AS applicant_race_name_3, COALESCE(applicant_race_3::TEXT, '') AS applicant_race_3, COALESCE(applicant_race_name_4::TEXT, '') AS applicant_race_name_4, COALESCE(applicant_race_4::TEXT, '') AS applicant_race_4, COALESCE(applicant_race_name_5::TEXT, '') AS applicant_race_name_5, COALESCE(applicant_race_5::TEXT, '') AS applicant_race_5, COALESCE(co_applicant_race_name_1::TEXT, '') AS co_applicant_race_name_1,COALESCE(co_applicant_race_1::TEXT, '') AS co_applicant_race_1, COALESCE(co_applicant_race_name_2::TEXT, '') AS co_applicant_race_name_2, COALESCE(co_applicant_race_2::TEXT, '') AS co_applicant_race_2, COALESCE(co_applicant_race_name_3::TEXT, '') AS co_applicant_race_name_3, COALESCE(co_applicant_race_3::TEXT, '') AS co_applicant_race_3, COALESCE(co_applicant_race_name_4::TEXT, '') AS co_applicant_race_name_4, COALESCE(co_applicant_race_4::TEXT, '') AS co_applicant_race_4, COALESCE(co_applicant_race_name_5::TEXT, '') AS co_applicant_race_name_5, COALESCE(co_applicant_race_5::TEXT, '') AS co_applicant_race_5, COALESCE(applicant_sex_name::TEXT, '') AS applicant_sex_name, COALESCE(applicant_sex::TEXT, '') AS applicant_sex, COALESCE(co_applicant_sex_name::TEXT, '') AS co_applicant_sex_name, COALESCE(co_applicant_sex::TEXT, '') AS co_applicant_sex, COALESCE(applicant_income_000s::TEXT, '') AS applicant_income_000s, COALESCE(purchaser_type_name::TEXT, '') AS purchaser_type_name, COALESCE(purchaser_type::TEXT, '') AS purchaser_type, COALESCE(denial_reason_name_1::TEXT, '') AS denial_reason_name_1, COALESCE(denial_reason_1::TEXT, '') AS denial_reason_1, COALESCE(denial_reason_name_2::TEXT, '') AS denial_reason_name_2, COALESCE(denial_reason_2::TEXT, '') AS denial_reason_2, COALESCE(denial_reason_name_3::TEXT, '') AS denial_reason_name_3, COALESCE(denial_reason_3::TEXT, '') AS denial_reason_3, COALESCE(TO_CHAR(rate_spread, 'FM00.00'), '') AS rate_spread, COALESCE(hoepa_status_name::TEXT, '') AS hoepa_status_name, COALESCE(hoepa_status::TEXT, '') AS hoepa_status, COALESCE(lien_status_name::TEXT, '') AS lien_status_name, COALESCE(lien_status::TEXT, '') AS lien_status, COALESCE(edit_status_name::TEXT, '') AS edit_status_name, COALESCE(edit_status::TEXT, '') AS edit_status, '' AS sequence_number, COALESCE("population"::TEXT, '') AS "population", COALESCE(minority_population::TEXT, '') AS minority_population, COALESCE(hud_median_family_income::TEXT, '') AS hud_median_family_income, COALESCE(tract_to_msamd_income::TEXT, '') AS tract_to_msamd_income, COALESCE(number_of_owner_occupied_units::TEXT, '') AS number_of_owner_occupied_units, COALESCE(number_of_1_to_4_family_units::TEXT, '') AS number_of_1_to_4_family_units, COALESCE(application_date_indicator::TEXT, '') AS application_date_indicator FROM Preliminary ORDER BY Preliminary.sequence_number) TO 'output.csv' WITH (FORMAT CSV, FORCE_QUOTE *, HEADER);